import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents: rounds 124.5 to 124 (banker\'s rounding)', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents: rounds 125.5 to 126 (banker\'s rounding)', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents: rounds 2.4 to 2', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents: rounds -0.5 to 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros: formats 123456 as "€1,234.56"', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros: formats -5 as "-€0.05"', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('formatEuros: formats 0 as "€0.00"', () => {
  assert.equal(formatEuros(0), '€0.00');
});

test('parseEuros: parses "12" to 1200', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros: parses "12.5" to 1250', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros: parses "1,234.56" to 123456', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('RATES: has EUR rate of 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES: has USD rate of 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES: has GBP rate of 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert: converts 10000 EUR to USD (10000 * 1.085 = 10850)', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert: converts 10000 EUR to GBP (10000 * 0.8425 = 8425)', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert: converts 10000 EUR to EUR (identity)', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert: returns error for unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert: converts 0 cents', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert: handles negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert: rounds to nearest cent', () => {
  // 1 EUR cent * 1.085 = 1.085 cents -> rounds to 1
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1);
});

test('convert: rounds 3 EUR cents to USD', () => {
  // 3 EUR cents * 1.085 = 3.255 cents -> rounds to 3
  const result = convert(3, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 3);
});

test('convert: rounds 5 EUR cents to GBP', () => {
  // 5 EUR cents * 0.8425 = 4.2125 cents -> rounds to 4
  const result = convert(5, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 4);
});

test('formatMoney: formats EUR with € symbol', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney: formats USD with $ symbol', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney: formats GBP with £ symbol', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney: formats negative USD', () => {
  assert.equal(formatMoney(-5000, 'USD'), '-$50.00');
});

test('formatMoney: formats negative GBP', () => {
  assert.equal(formatMoney(-5000, 'GBP'), '-£50.00');
});

test('formatMoney: formats small amount in USD', () => {
  assert.equal(formatMoney(5, 'USD'), '$0.05');
});

test('formatMoney: formats zero in GBP', () => {
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney: formats large amount with thousands separator', () => {
  assert.equal(formatMoney(1000000, 'USD'), '$10,000.00');
});

test('formatMoney: uses ? for unknown currency', () => {
  assert.equal(formatMoney(123456, 'JPY'), '?1,234.56');
});

test('convert and formatMoney round-trip: 100 EUR to USD and back', () => {
  const usd = convert(10000, 'USD');
  assert.equal(usd.ok, true);
  assert.equal(usd.value, 10850);
  const formatted = formatMoney(usd.value, 'USD');
  assert.equal(formatted, '$108.50');
});

test('convert: large amount EUR to USD', () => {
  // 1,000,000 EUR to USD
